    67	    public synchronized Reservation confirm(long reservationId) {
    68	        Reservation reservation = find(reservationId);
    69	        if (reservation.status() != ReservationStatus.PENDING) {
    70	            throw notAllowed(reservation, "confirm");
    71	        }
    72	        reservation.confirmPayment();
    73	        notifiers.forEach(n -> n.onConfirmation(reservation));
